parsed.update(EXTRA)
out = "{\n"
for k, v in parsed.items():
    out += f"  {json.dumps(k, ensure_ascii=False)}: {json.dumps(v, ensure_ascii=False)},\n"
out = out.rstrip() + "\n}\n"
PATH.write_text(out, encoding="utf-8")
print(f"total entries: {len(parsed)}")
